from datasets import load_from_disk
import numpy as np, math, random
from collections import defaultdict
from scipy.optimize import curve_fit, least_squares
from sklearn.linear_model import Ridge, HuberRegressor, LinearRegression
from sklearn.pipeline import make_pipeline
from sklearn.preprocessing import PolynomialFeatures
from sklearn.metrics import mean_squared_error, mean_absolute_error
from sklearn.model_selection import GroupShuffleSplit

rows=list(load_from_disk('/app/data'))
groups=sorted(set(r['group'] for r in rows))

def X(r): return math.log10(r['flops']) if 'flops' in r else r['log_flops']
def Y(r): return r['brier_score']

# Fit/predict functions return callable(group,x)

def fit_const(train):
    d={}
    glob=np.mean([Y(r) for r in train])
    for g in groups:
        ys=[Y(r) for r in train if r['group']==g]
        d[g]=float(np.mean(ys)) if ys else glob
    return lambda g,x: d.get(g,glob)

def fit_poly(train,deg=1,ridge=0.0):
    coefs={}; glob=np.mean([Y(r) for r in train])
    for g in groups:
        rs=[r for r in train if r['group']==g]
        if len(rs)<deg+1:
            coefs[g]=np.array([np.mean([Y(r) for r in rs]) if rs else glob])
        else:
            xs=np.array([X(r) for r in rs]); ys=np.array([Y(r) for r in rs])
            V=np.vstack([xs**i for i in range(deg+1)]).T
            if ridge:
                A=V.T@V+ridge*np.diag([0]+[1]*deg)
                b=V.T@ys
                c=np.linalg.solve(A,b)
            else:
                c=np.linalg.lstsq(V,ys,rcond=None)[0]
            coefs[g]=c
    def pred(g,x):
        c=coefs.get(g,np.array([glob])); return float(sum(c[i]*x**i for i in range(len(c))))
    return pred

def fit_power(train, shifted=False):
    params={}; glob=np.mean([Y(r) for r in train])
    # y = c + a*(f+s)^(-b) where f positive; x is log10 f
    for g in groups:
        rs=[r for r in train if r['group']==g]
        xs=np.array([r['flops'] for r in rs],float); ys=np.array([Y(r) for r in rs],float)
        if len(rs)<4:
            params[g]=(np.mean(ys) if len(ys) else glob,0,1,0)
            continue
        def fun(theta):
            c,a,b,s=theta
            if shifted:
                return c + a*np.power(xs+s, -b) - ys
            return c + a*np.power(xs, -b) - ys
        # try starts
        best=None
        starts=[]
        for c0 in [ys[-max(1,len(ys)//4):].mean(), ys.mean(), max(ys), min(ys)]:
            for b0 in [0.05,0.1,0.2,0.5,1.0]:
                starts.append([c0, ys[0]-c0, b0, 0.1])
        bounds=([-2,-5,-3,0],[1,5,3,10]) if shifted else ([-2,-5,-3,0],[1,5,3,0])
        for st in starts:
            try:
                res=least_squares(fun, st, bounds=bounds, max_nfev=10000, loss='linear')
                ss=np.mean(res.fun**2)
