from sklearn.metrics import mean_squared_error, mean_absolute_error, r2_score
rows=list(load_from_disk('/app/data')); groups=sorted(set(r['group'] for r in rows))
params={}
for g in groups:
    rs=[r for r in rows if r['group']==g]
    f=np.array([r['flops'] for r in rs],float); y=np.array([r['brier_score'] for r in rs],float)
    best=(1e9,None)
    def pred(t):
        a,b,c=t
        return a+b*np.power(f,-c)
    def res(t): return pred(t)-y
    # ordinary LS for final, bounds keep plausible
