# evaluate vertex clamp CV for quadratic
from datasets import load_from_disk
import numpy as np, math, random
from sklearn.metrics import mean_squared_error
rows=list(load_from_disk('/app/data')); groups=sorted(set(r['group'] for r in rows))
def Y(r):return r['brier_score']
def fit(train):
 co={}; glob=np.mean([Y(r) for r in train])
 for g in groups:
  rs=[r for r in train if r['group']==g]; x=np.array([r['log_flops'] for r in rs]); y=np.array([Y(r) for r in rs])
  V=np.vstack([np.ones_like(x),x,x*x]).T; co[g]=np.linalg.lstsq(V,y,rcond=None)[0]
 def p(g,x,mode):
  a,b,c=co.get(g,[glob,0,0])
  xx=x
  if mode=='vertex' and c<0 and b>0:
   v=-b/(2*c)
   if xx>v: xx=v
  y=a+b*xx+c*xx*xx
  return max(-1,min(0,float(y)))
 return p
for split in ['random','model','high']:
 print(split)
 for mode in ['plain','vertex']:
  rms=[]; rng=random.Random(3); reps=100 if split!='high' else 1
  for rep in range(reps):
   tr=[];te=[]
   if split=='random':
    for g in groups:
     for r in [r for r in rows if r['group']==g]:(te if rng.random()<.25 else tr).append(r)
   elif split=='model':
    models=list(set(r['model_name'] for r in rows)); rng.shuffle(models); t=set(models[:max(1,int(.25*len(models)))])
    tr=[r for r in rows if r['model_name'] not in t]; te=[r for r in rows if r['model_name'] in t]
   else:
    for g in groups:
     rs=sorted([r for r in rows if r['group']==g],key=lambda r:r['flops']); n=max(1,round(.25*len(rs))); tr+=rs[:-n]; te+=rs[-n:]
   p=fit(tr); yy=[Y(r) for r in te]; pp=[p(r['group'],r['log_flops'],mode) for r in te]
   rms.append(math.sqrt(mean_squared_error(yy,pp)))
  print(mode,np.mean(rms),np.std(rms))
